// ===========================================================================
//  CONFIGURACIÓN — el único sitio que hay que editar.
// ===========================================================================
const CONFIG = {
  // El mismo Ollama del semáforo y de los menús.
  ollama_url: 'https://ollama.com',
  modelo: 'gpt-oss:120b-cloud',

  // Más corto que el del semáforo a propósito: allí el color ya está puesto por
  // la matriz y esperar no le cuesta nada a nadie. Aquí hay una persona mirando
  // un botón, y Laravel corta a los 30 s.
  timeout_ms: 25000,

  // Tope de seguridad. Laravel ya manda sólo los que la empresa configuró (40
  // por defecto), pero esto evita que un ajuste a 200 mande un hilo enorme al
  // modelo y agote el worker.
  max_mensajes: 60,

  // Cuánto texto de cada mensaje. Un audio transcrito o un correo pegado pueden
  // traer miles de caracteres y el resumen no mejora por verlos enteros.
  max_chars_mensaje: 1200,
};

const body = $input.first().json.body ?? $input.first().json;

const empresa = body.empresa ?? {};
const conversacion = body.conversacion ?? {};
const tono = ['telegrama', 'neutro', 'informe'].includes(body.tono) ? body.tono : 'telegrama';
const mensajes = Array.isArray(body.mensajes) ? body.mensajes : [];

const problemas = [];
if (!conversacion.id) problemas.push('falta conversacion.id');
if (mensajes.length === 0) problemas.push('no llegaron mensajes');
if (!String(CONFIG.ollama_url).trim()) problemas.push('falta CONFIG.ollama_url');

if (problemas.length) {
  return [{ json: { guard: { ok: false, problemas }, conversacion_id: conversacion.id ?? null } }];
}

// EL ENCUADRE. El caso de uso es el traspaso: alguien coge un chat que no ha
// leído y tiene que contestar ya. El error que hay que evitar no es un resumen
// pobre —eso se nota y se abre el hilo— sino uno que CONTRADIGA lo que ya se le
// dijo al cliente. De ahí que lo prometido sea obligatorio y que inventar esté
// prohibido en dos sitios distintos.
const ESTILO = {
  telegrama: 'Máximo 3 frases cortas. Sin adornos, sin conectores largos.',
  neutro: '4 o 5 frases naturales.',
  informe: 'Redactado y completo, para dejar constancia escrita.',
};

const sistema = [
  'Resumes una conversación de atención al cliente por WhatsApp para un asesor que acaba de',
  'recibirla de un compañero y tiene que contestar ahora mismo.',
  'Tu única salida es un JSON. No le hablas al cliente y no redactas respuestas para él.',
  '',
  // Nombrar las claves aquí no es redundante con el `format` de abajo: Ollama
  // Cloud IGNORA el esquema en gpt-oss:120b-cloud (también ignora `think:false`
  // y devuelve `thinking`). Sin esto, el modelo bautiza las claves con los
  // conceptos del prompt —devolvía `pedido`/`promesa`/`pendientes`— y Laravel
  // descarta la respuesta entera por no encontrar `resumen`. 15-sep-2026.
  'EL JSON TIENE EXACTAMENTE ESTAS TRES CLAVES, con estos nombres y ningún otro:',
  '  "resumen":    texto corrido. Qué pasó en la conversación.',
  '  "puntos":     lista de textos. Lo que el cliente pidió y lo que se le prometió.',
  '  "pendientes": lista de textos. Lo que queda sin resolver.',
  '',
  'REGLAS:',
  '1. SÓLO lo que está en la conversación. Si algo no se dijo, no lo inventes ni lo deduzcas.',
  '2. Lo que el cliente pidió y lo que se le prometió van SIEMPRE. Si se le dio una fecha o un',
  '   compromiso, dilo con esas mismas palabras: el asesor va a contestar encima de eso.',
  '3. Lo que quede sin resolver va en "pendientes". Si no queda nada, devuelve la lista vacía;',
  '   inventar un pendiente hace que el asesor busque algo que no existe.',
  '4. No juzgues al cliente ni al agente, y no opines sobre la calidad de la atención.',
  '5. Español de Colombia, tercera persona, sin saludos ni despedidas.',
  '',
  'TONO: ' + tono + '. ' + ESTILO[tono],
].join('\n');

const hilo = mensajes
  .slice(-CONFIG.max_mensajes)
  .map((m) => (m.de === 'asesor' ? 'ASESOR: ' : 'CLIENTE: ')
    + String(m.texto ?? '').slice(0, CONFIG.max_chars_mensaje))
  .join('\n');

const usuario = [
  'Empresa: ' + (empresa.nombre || 'un proveedor de servicios'),
  'Contacto: ' + (conversacion.contacto || 'sin nombre'),
  '',
  'CONVERSACIÓN (de más antiguo a más reciente):',
  hilo,
].join('\n');

const ollamaRequest = {
  model: CONFIG.modelo,
  stream: false,
  think: false,
  // Algo más de temperatura que en el semáforo: aquí se redacta, y a cero salen
  // resúmenes cortados y telegráficos aunque se pida el tono largo. Pero baja,
  // porque lo que se resume son hechos.
  options: { temperature: 0.2, num_predict: 900 },
  // Salida estructurada: sin esto el modelo envuelve el JSON en una explicación
  // y Laravel lo descarta por no encontrar el campo `resumen`.
  format: {
    type: 'object',
    properties: {
      resumen: { type: 'string' },
      puntos: { type: 'array', items: { type: 'string' } },
      pendientes: { type: 'array', items: { type: 'string' } },
    },
    required: ['resumen', 'puntos', 'pendientes'],
    additionalProperties: false,
  },
  messages: [
    { role: 'system', content: sistema },
    { role: 'user', content: usuario },
  ],
};

return [{
  json: {
    guard: { ok: true, problemas: [] },
    conversacion_id: conversacion.id,
    ollama: { base_url: CONFIG.ollama_url, timeout_ms: CONFIG.timeout_ms },
    ollamaRequest,
  },
}];

// Saca el JSON de donde lo haya dejado Ollama y lo deja en la forma exacta que
// espera `ResumenIaClient`.
//
// Laravel tolera bastante —acepta `output`, `data`, alias en inglés y listas en
// texto— pero cuanto más limpio salga de aquí, menos hay que adivinar allí.
const entrada = $input.first().json;
const conversacion_id = $('Preparar resumen').first().json.conversacion_id ?? null;

let datos = null;

try {
  const crudo = entrada?.message?.content ?? entrada?.content ?? '';
  datos = typeof crudo === 'string' ? JSON.parse(crudo) : crudo;
} catch (e) {
  datos = null;
}

const lista = (v) => {
  if (typeof v === 'string') v = v.split(/\r?\n/);
  if (!Array.isArray(v)) return [];
  return v
    .map((x) => String(x ?? '').replace(/^\s*[-*•·]\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 8);
};

const resumen = String(datos?.resumen ?? '').trim();

// Un resumen vacío es tan inútil como ninguna respuesta, y Laravel lo trata
// como fallo. Mejor decirlo aquí que mandar un objeto a medias.
if (!resumen) {
  return [{ json: { resumen: '', puntos: [], pendientes: [], conversacion_id, error: 'el modelo no devolvió resumen' } }];
}

return [{
  json: {
    resumen: resumen.slice(0, 2000),
    puntos: lista(datos?.puntos),
    pendientes: lista(datos?.pendientes),
    conversacion_id,
  },
}];

// La rama de fallo. Devuelve la forma correcta con el resumen vacío: Laravel lo
// lee como «no se pudo» y le enseña al asesor un error claro en vez de un panel
// en blanco que parece una avería.
const g = $input.first().json.guard ?? {};

return [{
  json: {
    resumen: '',
    puntos: [],
    pendientes: [],
    conversacion_id: $input.first().json.conversacion_id ?? null,
    error: (g.problemas ?? ['no se pudo preparar el resumen']).join('; '),
  },
}];
